import p1v4_score as S  # noqa: E402

R = "data/p1v4/runs"
RES = "results/main_v04"
PARTS = ("r_hear", "s_move")
CONDS = {"r_hear": G.MATCHED, "s_move": G.S_CONDS}
SIDE_S = G.MATCHED
HIGH = {"r_hear": ("c0.9", "c0.99"), "s_move": ("mv0.9", "mv0.99")}
API = {"B3": "b3", "B2-fast": "b2fast", "B2-strong": "b2strong"}
B3_ALT = "B3 other setting"
CTL = "control (8 starts)"
NAT_EARS = "natural + ears (8 seeds)"
NAT_SEC8 = "natural + per-second ears (8 seeds)"
FAMILIES = {CTL: [f"control start {s}" for s in CS.STARTS], NAT_EARS: list(RX.NAT_EARS), NAT_SEC8: list(RX.NAT_SEC8)}
LISTENING = ("2d", "2c ears", "2b ears", "step 2 ears", "old head", "L2", "L3", "B3", B3_ALT, "shuffled", NAT_EARS,
             NAT_SEC8)
LEVELS = ("score", "score (no tolerance)", "decision")
TABLE = "configs/b2_detector_reliability_v1.txt"
TABLE_CLASS = {"phone ringing": "phone", "doorbell": "doorbell", "knocking": "knock"}


def settings(split):
    import p1v4_freeze as FZ
    return json.load(open(FZ.REHEARSAL))["settings"] if split == "dev" else FZ.verify_or_stop()["settings"]


def v06_fields(st, split, res):
    """v0.6 settings from the record: thresholds of the extra read-outs, B3's other answers setting, B2-strong's
    answers thresholds at K48 no thinking (perception gap), the tie tolerance. Dev: named fallbacks until the
    rehearsal record is rewritten; test and replication: all required."""
    fb = {}

    def need(ok, value, fallback, what):
        if ok:
            return value()
        if split != "dev":
            raise SystemExit(f"the freeze record has no {what} (package v0.6)")
        fb[what] = fallback[0]
        return fallback[1]()
    ans = lambda: json.load(open(f"{RES}/answer_only_dev.json"))          # noqa: E731

    def log_th(name, setting):
        e = next(x for x in ans()[name]["log"] if x["setting"] == setting)
        return {"setting": setting, "th_s": e["th_s"], "th_r": e["th_r"]}
    extra = need("extra" in st["readouts"], lambda: st["readouts"]["extra"],
                 (RX.RES, lambda: {n: {"th_s": e["th_s"], "th_r": e["th_r"]}
                                   for n, e in json.load(open(RX.RES))["readouts"].items()}),
                 "extra read-out thresholds")
    b3log = st["api"]["B3"].get("answers_log", {})
    alt = need("A6_nothink" in b3log, lambda: {"setting": "A6_nothink", "th_s": b3log["A6_nothink"]["th_s"],
                                               "th_r": b3log["A6_nothink"]["th_r"]},
               (f"{RES}/answer_only_dev.json B3 log", lambda: log_th("B3", "A6_nothink")), "B3 answers_log A6_nothink")
    pgs = st["api"]["B2-strong"].get("perception_gap_answers", {})
    pg = need(pgs.get("th_s") is not None, lambda: pgs,
              (f"{RES}/answer_only_dev.json B2-strong log", lambda: log_th("B2-strong", "K48_nothink_prec")),
              "B2-strong perception_gap_answers")
    tol = need("tie_tol" in st["grounding"], lambda: st["grounding"]["tie_tol"], ("GR.TIE_TOL", lambda: GR.TIE_TOL),
               "grounding tie_tol")
    res["dev_fallbacks"] = fb
    return extra, alt, pg, tol


def ci(c):
    keep = ("point", "ci95", "ci95_normal", "df", "dominant_factor", "n_clusters")
    return {k: c[k] for k in keep if k in c}


def t_ci(c, units, cl):
    """A plan-style interval (p1v4_score.interval, normal) turned into package v0.6's t interval."""
    t = GR.t_interval(units, cl, c["se"], c["one_way_se"], c["point"])
    return {"point": c["point"], **{k: t[k] for k in ("ci95", "ci95_normal", "df", "dominant_factor", "n_clusters")}}


# ------------------------------------------------------------------------------------------------ scores

def l1_family(z, st, ro):
    """Every L1-family read-out on one condition's features (as the final run's read-out pass, batch 1 here), with the
    extra read-outs of package v0.6 (15.3, 15.4)."""
    sec = R2D.Sec(None, z["ids"], z["sec_mean"], z["sec_max"])
    out = {"old head": RO.scores_of(z, None, None),
           "step 2 states": RO.scores_of(z, "states", ro["s2"]), "step 2 ears": RO.scores_of(z, "ears", ro["s2"]),
           "2b states": RO.scores_of(z, "states", ro["2b"]), "2b ears": RO.scores_of(z, "ears", ro["2b"]),
           "2c states": RO.scores_of(z, "states", ro["2c"]), "2c ears": RO.scores_of(z, "ears", ro["2c"]),
           "2d": R2D.scores_2d(z, sec, ro["2d"])}
    for s in CS.STARTS:
        out[f"control start {s}"] = RO.scores_of(z, "states", ro[f"start {s}"])
    rd = st["readouts"]
    th_old = {"S": st["local"]["L1"]["th_s"], "R": st["local"]["L1"]["th_r"]}
    out["conditional"] = CV.conditional(z, ro["s2"], ro["probe"], th_old, {"S": rd["step 2 ears"]["th_s"],
                                                                           "R": rd["step 2 ears"]["th_r"]})[0]
    out["2b conditional"] = CV.conditional(z, ro["2b"], ro["probe"], th_old, {"S": rd["2b ears"]["th_s"],
                                                                             "R": rd["2b ears"]["th_r"]})[0]
    for n in RX.NAMES:
        out[n] = RX.scores(n, z, ro["extra"][n])
    pe = CV.probe_p(z["ears"], ro["probe"])                     # the ears probe (7.3): P(event), R-hear only
    out["ears probe"] = {}
    for w, idv in enumerate(z["ids"]):
        u, v, k = idv.split("|")
        out["ears probe"][(u, v, int(k))] = {"R": float(1 - pe[w])}
    return out


def thresholds(st, extra):
    rd = st["readouts"]
    th = {n: (rd[n]["th_s"], rd[n]["th_r"]) for n in rd if n not in ("control starts", "extra")}
    th.update({f"control start {s}": (v["th_s"], v["th_r"]) for s, v in rd["control starts"].items()})
    th.update({n: (e["th_s"], e["th_r"]) for n, e in extra.items()})
    th["old head"] = (st["local"]["L1"]["th_s"], st["local"]["L1"]["th_r"])
    for n in ("L2", "L3", "T"):
        th[n] = (st["local"][n]["th_s"], st["local"][n]["th_r"])
    th["ears probe"] = (0.5, 1 - CV.EARS_CUT)
    return th


def read_api(path, groups, sd):
    got = {}
    for line in open(path, encoding="utf-8"):
        rec = json.loads(line)
        if rec["status"] == 200:
            got[(rec["id"], rec["q"])] = rec["score"]
    sc = {}
    for g in groups:
        q = "R" if g["part"] == "r_hear" else "S"
        for v in g["versions"]:
            src = f"{g['unit']}|{v if sd == 'b3' else '2'}|{g['k']}"
            if (src, q) in got:
                sc[(g["unit"], v, g["k"])] = {q: got[(src, q)]}
    return sc


def api_scores(split, cond, groups, st, alt):
    """The API systems in one matched condition, in the mode the probe fixed. B2 readers: asked once per group on
    version 2's identical input. B3 also in its other setting (15.6): without the table when the day is answers-only,
    with the table (always on answers) when the day has probabilities."""
    out, mode, paths = {}, {}, {}

    def gate(p):                                       # amendment 13.1: no metric with a missing answer on test
        mp = os.path.join(os.path.dirname(p), "missing.json")
        if split != "dev" and os.path.exists(p):
            if not os.path.exists(mp) or json.load(open(mp))["missing"]:
                raise SystemExit(f"{p}: missing answers or no missing.json (rerun the package API command)")
    for name, sd in API.items():
        m, e_eff = G.api_effective(sd, split)          # frozen setting, or today's re-choice (amendment 13.2)
        answers = m == "answers"
        mode[name] = m + (" (re-chosen)" if e_eff["override"] else "")
        p = os.path.join(G.api_dir(split, sd, e_eff["setting"], answers), cond, "responses.jsonl")
        paths[name] = p
        if os.path.exists(p):
            gate(p)
            out[name] = (read_api(p, groups, sd), (e_eff["th_s"], e_eff["th_r"]))
        if name == "B3":
            e = alt if answers else st["api"]["B3"]["answers"]
            pa = os.path.join(G.api_dir(split, "b3", e["setting"], True), cond, "responses.jsonl")
            paths[B3_ALT] = pa
            mode[B3_ALT] = f"answers ({e['setting']})"
            if os.path.exists(pa):
                gate(pa)
                out[B3_ALT] = (read_api(pa, groups, "b3"), (e["th_s"], e["th_r"]))
    return out, mode, paths


# ------------------------------------------------------------------------------------------------ main

def main(split, out=None, row_hook=None, z_hook=None, with_natural=True):
    """row_hook(rows) and z_hook(cond, z) change the inputs in memory: only for selftest() (amendment 4.5)."""
    st = settings(split)
    res = {"split": split, "package": "v0.6", "missing": [], "identity": {}, "m1": {}, "criteria": {},
           "reported": {}}
    extra, alt, pg_th, tol = v06_fields(st, split, res)
    rows, rows_by = G.load(split)
    if row_hook:
        rows = row_hook(rows)
        rows_by = {(r["unit"], r["version"]): r for r in rows}
    groups_all = G.load_groups(split)
    gpart = {g["unit"]: g["part"] for g in groups_all}
    cl = GR.cluster_table(rows, split)
    th = thresholds(st, extra)
    ro = {"s2": RO.load_readouts(), "2b": AC.load_allclass(), "2c": R2C.load_2c(), "2d": R2D.load_2d(),
          "probe": dict(np.load(f"{R}/readout/ears_probe.npz")), "extra": {n: RX.load(n) for n in RX.NAMES}}
    for s in CS.STARTS:
        ro[f"start {s}"] = CS.load_start(s)
    margin, g4m = st["grounding"]["margin"], st["grounding"]["g4_margin"]

    # 1. scores and identity per matched condition
    evs, ev0, evd, dsc, bad = {}, {}, {}, {}, collections.defaultdict(set)
    keep_sc = {}
    api_mode = {}
    for cond in G.MATCHED + G.MOVE_CONDS:
        groups_c = [g for g in groups_all if g["part"] == "s_move"] if G.is_move(cond) else groups_all
        units_c = {g["unit"] for g in groups_c}
        p = f"{G.out_dir(split)}/l1_{cond}.npz"
        if not os.path.exists(p):
            res["missing"].append(f"l1 {cond}")
            continue
        z = dict(np.load(p))
        if z_hook:
            z = z_hook(cond, z)
        if "sec_mean" not in z:
            raise SystemExit(f"{p} has no per-second ears: rerun `p1v4_grounding.py l1 {split}` (v0.5)")
        sh = collections.defaultdict(set)
        for idv, h in zip(z["ids"], z["text_sha"]):
            sh[idv.split("|")[0]].add(str(h))
        bad[cond] |= {u for u, s in sh.items() if len(s) > 1 and u in units_c}
        scores = {n: (sc, th[n]) for n, sc in l1_family(z, st, ro).items()}
        loc = GR.local_scores(split, cond)
        if loc is None:
            res["missing"].append(f"local {cond}")
        else:
            shl = collections.defaultdict(set)
            for k, h in loc["_sha"].items():
                shl[k.split("|")[0]].add(h)
            bad[cond] |= {u for u, s in shl.items() if len(s) > 1 and u in units_c}
            for n in ("T", "L2", "L3"):
                scores[n] = (loc[n], th[n])
            comb, _ = CP.combine(scores["old head"][0], loc["L3"], "logit", 0.5)
            scores["combination"] = (comb, th["combination"])
        api, api_mode, paths = api_scores(split, cond, groups_c, st, alt)
        for name in list(API) + [B3_ALT]:
            if name not in api:
                res["missing"].append(f"api {name} {cond}")
        for name in ("B3", B3_ALT):                                  # B3 hears every version: identical text needed
            cp = os.path.join(os.path.dirname(paths[name]), "case_sha.json")
            if os.path.exists(cp):
                sa = collections.defaultdict(set)
                for k, h in json.load(open(cp)).items():
                    sa[k.split("|")[0]].add(h)
                bad[cond] |= {u for u, s_ in sa.items() if len(s_) > 1 and u in units_c}
        scores.update(api)
        for name, (sc, t) in scores.items():
            dec = S.decide(sc, *t)
            evs[(name, cond)] = GR.group_eval(groups_c, rows_by, dec, sc, tol=tol)
            ev0[(name, cond)] = GR.group_eval(groups_c, rows_by, dec, sc, tol=0.0)
            evd[(name, cond)] = GR.group_eval(groups_c, rows_by, dec, None)
            if name in ("2d", "2c ears"):
                keep_sc[(name, cond)] = sc
            if cond in G.MATCHED and (name in ("2d", "2c states", "2b states", "step 2 states", "old head")
                                      or name.startswith("control")):
                for v in ("2", "3"):
                    dsc[(name, cond, v)] = {g["unit"]: sc[(g["unit"], v, g["k"])]["R"] - sc[(g["unit"], "1", g["k"])]["R"]
                                            for g in groups_all if g["part"] == "r_hear"}
        if loc is not None:
            for E in (evs, ev0, evd):
                E[("B1-strong", cond)] = GR.group_eval(groups_c, rows_by, loc["B1-strong"])
    if split != "dev" and res["missing"]:
        raise SystemExit(f"missing inputs on {split}: {res['missing']} (review C-M10: no criterion on partial inputs)")
    dropped = set().union(*bad.values()) if bad else set()
    subset_of = {g["unit"]: rows_by[(g["unit"], "1")]["subset"] for g in groups_all}
    main_units = {p: [g["unit"] for g in groups_all if g["part"] == p and subset_of[g["unit"]] is None
                      and g["unit"] not in dropped] for p in PARTS}
    n_main = sum(1 for g in groups_all if subset_of[g["unit"]] is None)
    share = len([u for u in dropped if subset_of.get(u) is None]) / max(1, n_main)
    res["identity"] = {"dropped_groups": sorted(dropped), "dropped_share_main": share,
                       "invalid": share > st["grounding"]["invalid_share"], "by_condition": {c: len(b) for c, b in bad.items()},
                       "n_main_groups": {p: len(u) for p, u in main_units.items()},
                       "subsets": dict(collections.Counter(str(s) for s in subset_of.values()))}
    res["api_modes"] = api_mode
    res["tie_tol"] = tol
    names = sorted({n for n, _ in evs})
    gap_units = collections.Counter()

    def unit_val(ev, n, c, u, field, v):
        x = ev[(n, c)].get(u)
        if x is None:                         # a group with a missing answer (design review minor 9): wrong, ties
            gap_units[(n, c)] += 1
            return 0.0 if field == "right" else 0.5
        return x["pair"][v] if v else x[field]

    def pu(ev, n, part, field, v=None, units=None, conds=None):
        units = units if units is not None else main_units[part]
        conds = conds if conds is not None else CONDS[part]
        if n in FAMILIES:
            return np.mean([pu(ev, m, part, field, v, units, conds) for m in FAMILIES[n]], 0)
        return np.array([np.mean([unit_val(ev, n, c, u, field, v) for c in conds if (n, c) in ev]) for u in units])

    def have(n, part, conds=None):
        conds = conds if conds is not None else CONDS[part]
        if n in FAMILIES:
            return all(have(m, part, conds) for m in FAMILIES[n])
        if n == "ears probe" and part != "r_hear":                    # the probe answers "event or not" (R-hear)
            return False
        return all((n, c) in evs for c in conds)

    def crit(part, a, b=None, minus=0.0, absdiff=None, units=None):
        us = units if units is not None else main_units[part]
        if absdiff is not None:
            c = GR.criterion(us, cl, {}, lambda w: (GR.wmean(w, a) - 0.5) - abs(GR.wmean(w, absdiff) - 0.5),
                             lambda: float((a.mean() - 0.5) - abs(absdiff.mean() - 0.5)))
        elif b is not None:
            c = GR.criterion(us, cl, {}, lambda w: GR.wmean(w, a) - GR.wmean(w, b), lambda: float(a.mean() - b.mean()))
        else:
            c = GR.criterion(us, cl, {}, lambda w: GR.wmean(w, a) - minus, lambda: float(a.mean() - minus))
        return ci(c)

    def passed(g, need_margin):
        g["pass"] = bool((g["point"] >= need_margin if need_margin is not None else True) and g["ci95"][0] > 0)
        return g

    # 2. measurement 1 per system
    for n in names + list(FAMILIES):
        res["m1"][n] = {}
        for part in PARTS:
            for tag, conds in (("", CONDS[part]), (" side (ring-class labels)", SIDE_S if part == "s_move" else None)):
                if conds is None or not main_units[part] or not have(n, part, conds):
                    continue
                x = {lvl: {f: float(pu(ev, n, part, f, conds=conds).mean())
                           for f in ("right", "conc", "follow_event", "follow_none")}
                     for lvl, ev in zip(LEVELS, (evs, ev0, evd))}
                vs = ("2", "3") if part == "r_hear" else ("2", "3", "4")
                x["pairs"] = {lvl: {v: float(pu(ev, n, part, None, v, conds=conds).mean()) for v in vs}
                              for lvl, ev in zip(LEVELS, (evs, ev0, evd))}
                if n not in FAMILIES:
                    x["by_condition"] = {c: GR.summarise({u: evs[(n, c)][u] for u in main_units[part]
                                                          if u in evs[(n, c)]}, part) for c in conds}
                x["grounded_ci"] = crit(part, pu(evd, n, part, "right", conds=conds))
                res["m1"][n][part + tag] = x
        if not res["m1"][n]:
            del res["m1"][n]
    for part in PARTS:                                                   # amendment 11.3 and package 15.6
        for n in LISTENING:
            if not main_units[part] or not have(n, part):
                continue
            se_none = pu(evd, n, part, "follow_event", conds=("none",)) - pu(evd, n, part, "follow_none", conds=("none",))
            res["reported"].setdefault("no_label_sound_effect", {}).setdefault(part, {})[n] = crit(part, se_none)
            hi = [c for c in HIGH[part]]
            se_hi = pu(evd, n, part, "follow_event", conds=hi) - pu(evd, n, part, "follow_none", conds=hi)
            g = passed(crit(part, se_none, se_hi), margin)
            g["sound_effect_none"], g["sound_effect_high"] = float(se_none.mean()), float(se_hi.mean())
            res["reported"].setdefault("heard_then_overridden", {}).setdefault(part, {})[n] = g

    # 3. criteria
    if res["identity"]["invalid"]:
        res["criteria"] = {"invalid": f"{share:.1%} of the main groups dropped by the input identity check (> 2%)"}
    else:
        rh, sm = "r_hear", "s_move"
        K = {"note": ("pass flags: grounded-accuracy criteria in 'grounded'; concordance criteria at the score level "
                      f"with ties below {tol} ('score'); G1b at the decision level; the other levels are reported")}
        Gd = {}
        for part, tag in ((rh, ""), (sm, "-S")):
            g1 = crit(part, pu(evd, "2d", part, "right"))
            g1["pass"] = bool(g1["ci95"][0] > 0.5)
            Gd[f"G1a{tag}: main grounded group accuracy, lower bound > 0.5"] = g1
            g6 = passed(crit(part, pu(evd, "2d", part, "right"), pu(evd, NAT_SEC8, part, "right")), margin)
            Gd[f"G6a{tag}: main - natural-label per-second read-out (8 seeds), grounded"] = g6
        Gd["G4a: main - 2c ears, stop grounded group accuracy"] = passed(
            crit(sm, pu(evd, "2d", sm, "right"), pu(evd, "2c ears", sm, "right")), g4m)
        Gd["G4a (described): main - 2c ears, respond grounded"] = crit(rh, pu(evd, "2d", rh, "right"),
                                                                       pu(evd, "2c ears", rh, "right"))
        Gd["G4c: main - shuffled seconds, stop grounded group accuracy"] = passed(
            crit(sm, pu(evd, "2d", sm, "right"), pu(evd, "shuffled", sm, "right")), g4m)
        Gd["G4c (described): main - shuffled seconds, respond grounded"] = crit(rh, pu(evd, "2d", rh, "right"),
                                                                                pu(evd, "shuffled", rh, "right"))
        K["grounded"] = Gd
        b3s = [n for n in ("B3", B3_ALT) if have(n, rh)]                       # 15.6: the more grounded B3 setting
        if b3s:
            best = max(b3s, key=lambda n: float(pu(evd, n, rh, "conc").mean()))
            g = passed(crit(rh, pu(evd, "2d", rh, "conc"), pu(evd, best, rh, "conc")), margin)
            g.update(level="decision", b3_setting_used=best, b3_mode=api_mode.get(best),
                     b3_concordance={n: float(pu(evd, n, rh, "conc").mean()) for n in b3s})
            K["G1b: main - B3 (more grounded setting), decision-level concordance"] = g
            if have(best, sm):
                K["G1b (stop, reported): main - B3, decision level"] = crit(sm, pu(evd, "2d", sm, "conc"),
                                                                             pu(evd, best, sm, "conc"))
            if api_mode.get("B3") == "probabilities":
                K["G1b (score level, reported): main - B3"] = crit(rh, pu(evs, "2d", rh, "conc"),
                                                                    pu(evs, "B3", rh, "conc"))
        for level, ev in zip(LEVELS, (evs, ev0, evd)):
            L = {}
            score = level == "score"
            for part, tag in ((rh, ""), (sm, "-S")):
                g2a = crit(part, pu(ev, "2c states", part, "conc"), absdiff=pu(ev, "old head", part, "conc"))
                L[f"G2a{tag}: (rung-2 states - 0.5) - |old head - 0.5|"] = passed(g2a, margin) if score else g2a
                g2b = crit(part, pu(ev, "2c states", part, "conc"), pu(ev, CTL, part, "conc"))
                L[f"G2b{tag}: rung-2 states - natural-label control"] = passed(g2b, margin) if score else g2b
            for name, a, b, minus in (
                    ("G3a: step 2 states - control (presence)", pu(ev, "step 2 states", rh, None, "2"),
                     pu(ev, CTL, rh, None, "2"), None),
                    ("G3a absolute: step 2 states presence - 0.5", pu(ev, "step 2 states", rh, None, "2"), None, 0.5),
                    ("G3b: rung-2 states - step 2 states (identity)", pu(ev, "2c states", rh, None, "3"),
                     pu(ev, "step 2 states", rh, None, "3"), None),
                    ("G3b absolute: rung-2 states identity - 0.5", pu(ev, "2c states", rh, None, "3"), None, 0.5)):
                g = crit(rh, a, b) if b is not None else crit(rh, a, minus=minus)
                L[name] = passed(g, margin) if score else g
            g = crit(rh, pu(ev, "step 2 states", rh, None, "3"), pu(ev, CTL, rh, None, "3"))
            g["rise_below_0.20"] = bool(g["point"] < margin)
            L["side rung 1: identity change, step 2 states - control"] = g
            g = crit(rh, pu(ev, "2c states", rh, None, "2"), pu(ev, "step 2 states", rh, None, "2"))
            g["drop_below_0.20"] = bool(g["point"] > -margin)
            L["side rung 2: presence change, rung-2 states - step 2 states"] = g
            L["G3c (described): rung-2 states - 2b states, stop concordance"] = crit(sm, pu(ev, "2c states", sm, "conc"),
                                                                                     pu(ev, "2b states", sm, "conc"))
            for v in ("2", "3", "4"):
                L[f"stop pair 1 vs {v}: rung-2 states - control"] = crit(sm, pu(ev, "2c states", sm, None, v),
                                                                         pu(ev, CTL, sm, None, v))
                L[f"stop pair 1 vs {v}: rung-2 states - |control - 0.5| form"] = crit(
                    sm, pu(ev, "2c states", sm, None, v), absdiff=pu(ev, CTL, sm, None, v))
            K[level] = L
        for v, lab in (("2", "presence"), ("3", "identity")):          # event-score differences, R-hear
            us = main_units[rh]

            def dvec(n):
                if n == CTL:
                    return np.mean([dvec(m) for m in FAMILIES[CTL]], 0)
                return np.array([np.mean([dsc[(n, c, v)][u] for c in G.MATCHED]) for u in us])
            for n in ("2d", "2c states", "old head", CTL):          # positive: version 1 has the higher event score
                K.setdefault("event_score_difference", {})[f"{n}: {lab}"] = crit(rh, dvec(n))
            K["event_score_difference"][f"rung 2 - rung 1: {lab}"] = crit(rh, dvec("2c states"), dvec("step 2 states"))
            K["event_score_difference"][f"rung 1 - control: {lab}"] = crit(rh, dvec("step 2 states"), dvec(CTL))
        for name, path, key, label in (
                ("G4b", f"{RES}/offsets_2d_{split}.json", "rule 4: shifted offsets, 2d - 2c ears group all-right >= +0.10",
                 "G4b (offsets file, all groups; reported: the criterion is the row recomputed below)"),
                ("G5", f"{RES}/noise_{split}.json", "G5", "G5 (own run)")):
            if os.path.exists(path):
                K[label] = json.load(open(path)).get(key)
            elif split != "dev":
                raise SystemExit(f"{path} missing: run it before the report (amendment 13.2)")
        po = f"{RES}/offsets_2d_{split}.json"                    # 15.3: G4b without the identity-dropped groups
        g4b_arrays = None
        if os.path.exists(po) and "per_unit_right" in json.load(open(po)):
            pr_ = json.load(open(po))["per_unit_right"]
            us = [u for u in main_units[sm] if all(u in pr_["2d"][d] for d in pr_["2d"])]
            sh = [d for d in pr_["2d"] if float(d) != 0.0]
            a = np.array([np.mean([pr_["2d"][d][u] for d in sh]) for u in us])
            b = np.array([np.mean([pr_["2c ears"][d][u] for d in sh]) for u in us])
            g4b_arrays = (a, b, us)
            K["G4b: shifted offsets, main - 2c ears, stop grounded"] = passed(crit(sm, a, b, units=us), g4m)
        elif split != "dev":
            raise SystemExit(f"{po} has no per-unit values: rerun `p1v4_readout_2d.py offsets {split}`")
        res["criteria"] = K

        # post-fix review minor 1: the verdicts use bootstrap seed 1 (B = 2000, as registered); seeds 2-6 reported
        def mc_crit():
            o = {}
            for part, tag in ((rh, ""), (sm, "-S")):
                o[f"G1a{tag}"] = (crit(part, pu(evd, "2d", part, "right")), "lower > 0.5")
                o[f"G6a{tag}"] = (crit(part, pu(evd, "2d", part, "right"), pu(evd, NAT_SEC8, part, "right")), margin)
                o[f"G2a{tag}"] = (crit(part, pu(evs, "2c states", part, "conc"),
                                       absdiff=pu(evs, "old head", part, "conc")), margin)
                o[f"G2b{tag}"] = (crit(part, pu(evs, "2c states", part, "conc"), pu(evs, CTL, part, "conc")), margin)
            o["G4a"] = (crit(sm, pu(evd, "2d", sm, "right"), pu(evd, "2c ears", sm, "right")), g4m)
            o["G4c"] = (crit(sm, pu(evd, "2d", sm, "right"), pu(evd, "shuffled", sm, "right")), g4m)
            o["G3a"] = (crit(rh, pu(evs, "step 2 states", rh, None, "2"), pu(evs, CTL, rh, None, "2")), margin)
            o["G3b"] = (crit(rh, pu(evs, "2c states", rh, None, "3"), pu(evs, "step 2 states", rh, None, "3")), margin)
            if b3s:
                o["G1b"] = (crit(rh, pu(evd, "2d", rh, "conc"), pu(evd, best, rh, "conc")), margin)
            if g4b_arrays is not None:
                o["G4b"] = (crit(sm, g4b_arrays[0], g4b_arrays[1], units=g4b_arrays[2]), g4m)
            return o

        def verdict(g, rule):
            return bool(g["ci95"][0] > 0.5) if rule == "lower > 0.5" else bool(g["point"] >= rule and g["ci95"][0] > 0)
        mc = collections.defaultdict(list)
        try:
            for seed in (1, 2, 3, 4, 5, 6):
                GR.BOOT_SEED = seed
                for name, (g, rule) in mc_crit().items():
                    mc[name].append((seed, g["ci95"][0], verdict(g, rule)))
        finally:
            GR.BOOT_SEED = 1
        res["reported"]["monte_carlo_seeds"] = {
            name: {"lower_bound_by_seed": {s: lb for s, lb, _ in v}, "passes_out_of_6": sum(p for _, _, p in v),
                   "same_verdict_in_all_seeds": len({p for _, _, p in v}) == 1} for name, v in mc.items()}

        # 4. reported rows of 15.4 and 15.8
        rep = res["reported"]
        rep["two_by_two"] = {part: {n: crit(part, pu(evd, n, part, "right")) for n in ("2d", "2c ears", NAT_EARS, NAT_SEC8)
                                    if have(n, part)} for part in PARTS}
        rep["two_by_two_effects"] = {part: {
            "labels at pooled ears: 2c ears - natural + ears": crit(part, pu(evd, "2c ears", part, "right"),
                                                                    pu(evd, NAT_EARS, part, "right")),
            "time under natural labels: natural + per-second - natural + ears": crit(
                part, pu(evd, NAT_SEC8, part, "right"), pu(evd, NAT_EARS, part, "right"))} for part in PARTS}
        rep["second_seeds"] = {
            "2c states s1 grounded": {p: crit(p, pu(evd, "2c states s1", p, "right")) for p in PARTS},
            "2d s1 grounded": {p: crit(p, pu(evd, "2d s1", p, "right")) for p in PARTS},
            "G2a with 2c states s1 (score)": {p: crit(p, pu(evs, "2c states s1", p, "conc"),
                                                      absdiff=pu(evs, "old head", p, "conc")) for p in PARTS},
            "G2b with 2c states s1 (score)": {p: crit(p, pu(evs, "2c states s1", p, "conc"),
                                                      pu(evs, CTL, p, "conc")) for p in PARTS},
            "G4a with 2d s1": crit(sm, pu(evd, "2d s1", sm, "right"), pu(evd, "2c ears", sm, "right"))}
        rep["ears_ladder"] = {part: {n: crit(part, pu(evd, n, part, "right")) for n in
                                     ("step 2 ears", "2b ears", "2c ears", "2d") if have(n, part)} for part in PARTS}
        if have("ears probe", rh):
            rep["ears_ladder"]["ears probe concordance (R-hear, score)"] = crit(rh, pu(evs, "ears probe", rh, "conc"))
        rep["graded"] = {
            "main grounded at c >= 0.9": {p: crit(p, pu(evd, "2d", p, "right", conds=HIGH[p])) for p in PARTS},
            "main grounded, respond, by class": {
                cls: crit(rh, pu(evd, "2d", rh, "right", units=us), units=us) for cls, us in (
                    ("phone", [u for u in main_units[rh] if gclass(groups_all, u) == "phone"]),
                    ("door", [u for u in main_units[rh] if gclass(groups_all, u) in ("doorbell", "knock")])) if us},
            "main grounded, stop, by door recording group": {
                str(dg): {"n": len(us), "grounded": float(pu(evd, "2d", sm, "right", units=us).mean())}
                for dg, us in group_by(main_units[sm], lambda u: cl[u][2]).items()}}
        rep["threshold_grid_stop"] = threshold_grid(keep_sc, groups_all, rows_by, main_units[sm], th)
        rep["calibration_t_stop"] = GR.calibrate_t(main_units[sm], cl)
        # package 4.1 (post-fix review M6): the unseen subsets, described per subset (no criterion, no interval)
        rep["subsets"] = {}
        for sub in sorted({str(x) for x in subset_of.values() if x is not None}):
            for part in PARTS:
                us = [g["unit"] for g in groups_all if g["part"] == part and str(subset_of[g["unit"]]) == sub
                      and g["unit"] not in dropped]
                if us:
                    rep["subsets"].setdefault(sub, {})[part] = {
                        "n_groups": len(us), "grounded_group_accuracy": {
                            n: float(pu(evd, n, part, "right", units=us).mean())
                            for n in names + list(FAMILIES) if have(n, part)}}
        # package 15.9 (post-fix review M7): the old head's sentence follows its numbers, per decision
        rep["old_head_wording"] = {}
        for part in PARTS:
            x = res["m1"].get("old head", {}).get(part)
            if x:
                diffs = {c: s["follow_event"] - s["follow_none"] for c, s in x["by_condition"].items()}
                conc = x["decision"]["conc"]
                mean_d = float(np.mean(list(diffs.values())))
                still = bool(abs(conc - 0.5) <= 0.05 and max(abs(v) for v in diffs.values()) < 0.05)
                rep["old_head_wording"][part] = {
                    "decision_concordance": conc, "grounded": x["decision"]["right"],
                    "follow_event_minus_follow_others_by_condition": diffs, "mean_follow_difference": mean_d,
                    "did_not_change_with_the_audio": still,
                    "direction": "none" if still else "right way" if mean_d > 0 else "wrong way"}
        rep["groups_missing_answers"] = {f"{n} {c}": k for (n, c), k in gap_units.items()}

    # 5. natural inputs
    if with_natural:
        res["natural"] = natural(split, st, rows, cl, pg_th, extra)
        for n, c in res["natural"].get("candidates", {}).items():       # amendment 1.4: the table's grounded columns
            m = res["m1"].get(n, {})
            c["grounded"] = {p: m[p]["grounded_ci"] for p in PARTS if p in m}
    json.dump(res, open(out or f"{RES}/grounding_v06_{split}.json", "w"), indent=1, default=str)
    show(res)
    return res


def gclass(groups, u):
    for g in groups:
        if g["unit"] == u:
            return g["event"][0]
    return None


def group_by(units, key):
    out = collections.defaultdict(list)
    for u in units:
        out[key(u)].append(u)
    return dict(out)


def threshold_grid(keep_sc, groups, rows_by, units, th):
    """15.8: stop grounded rate of the main system and 2c ears over S thresholds 0.05-0.60, at each other's threshold,
    and each one's best single threshold (S-move, conditions none and mv*)."""
    sm = [g for g in groups if g["part"] == "s_move" and g["unit"] in set(units)]
    grid = [round(x, 2) for x in np.arange(0.05, 0.601, 0.05)]

    def rate(name, ts):
        vals = []
        for c in G.S_CONDS:
            sc = keep_sc.get((name, c))
            if sc is None:
                return None
            ev = GR.group_eval(sm, rows_by, S.decide(sc, ts, 0.5), None)
            vals.append(np.mean([ev[g["unit"]]["right"] for g in sm if g["unit"] in ev]))
        return float(np.mean(vals))
    out = {n: {str(t): rate(n, t) for t in grid} for n in ("2d", "2c ears")}
    out["2d at 2c ears' threshold"] = rate("2d", th["2c ears"][0])
    out["2c ears at 2d's threshold"] = rate("2c ears", th["2d"][0])
    for n in ("2d", "2c ears"):
        vals = {t: v for t, v in out[n].items() if v is not None}
        if vals:
            t_best = max(vals, key=vals.get)
            out[f"{n} best single threshold"] = {"th_s": float(t_best), "grounded": vals[t_best]}
        out[f"{n} own threshold"] = {"th_s": th[n][0], "grounded": rate(n, th[n][0])}
    return out


# ------------------------------------------------------------------------------------------------ natural inputs

def reliability_table():
    """configs/b2_detector_reliability_v1.txt -> {(class, band index): share right} for the event classes."""
    out = {}
    for line in open(TABLE, encoding="utf-8"):
        m = re.match(r"- ([a-z ]+): (.*)", line.strip())
        if not m or m.group(1) not in TABLE_CLASS:
            continue
        shares = [int(x) / 100 for x in re.findall(r"(\d+)% right", m.group(2))]
        for b, s in enumerate(shares):
            out[(TABLE_CLASS[m.group(1)], b)] = s
    return out


def band_of(c):
    for i, (lo, hi) in enumerate(GR.BANDS):
        if lo <= c < hi:
            return i
    return None


def label_points(rows, split):
    """R-hear main-body points with an event-class detection (>= 0.2) in the window: the strongest one's class and
    confidence, whether an event was really there, the line's transcript check and the speaker-tag check."""
    ctx = C.Context(split)
    ex = S.excluded_units()
    pts = []
    for r in rows:
        if r["unit"] in ex or r["part"] != "r_hear" or r["subset"] is not None:
            continue
        p = r["points"][0]
        tr, _, tags, snd = ctx.point(r, p["k"])
        snd = [s for s in snd if RO.in_window(s, p["t"])]
        if not snd:
            continue
        top = max(snd, key=lambda s: s[3])
        if top[3] < 0.2:
            continue
        pts.append({"key": (r["unit"], r["version"], p["k"]), "unit": r["unit"], "cls": top[0], "conf": float(top[3]),
                    "band": band_of(top[3]), "real": bool(RO.is_real(r, p["t"])), "gold": p["gold"]["R"]})
    return pts


def cmh(pts, follow, units, cl):
    """Cochran-Mantel-Haenszel-weighted (follow | real label) - (follow | false label) over the strata band x class,
    with the package's t interval (units = cluster units). follow: {key: bool}."""
    strata = sorted({(p["band"], p["cls"]) for p in pts})
    si = {s: j for j, s in enumerate(strata)}
    ui = {u: i for i, u in enumerate(units)}
    nr, nf, fr, ff = (np.zeros((len(units), len(strata))) for _ in range(4))
    for p in pts:
        i, j = ui[p["unit"]], si[(p["band"], p["cls"])]
        f = float(follow.get(p["key"], False))
        if p["real"]:
            nr[i, j] += 1
            fr[i, j] += f
        else:
            nf[i, j] += 1
            ff[i, j] += f

    def stat(w):
        NR, NF, FR, FF = w @ nr, w @ nf, w @ fr, w @ ff
        wt = NR * NF / np.maximum(NR + NF, 1e-9)
        d = FR / np.maximum(NR, 1e-9) - FF / np.maximum(NF, 1e-9)
        return (wt * d).sum(1) / np.maximum(wt.sum(1), 1e-9)
    table = {f"{GR.BANDS[b][0]:.2f}-{min(GR.BANDS[b][1], 1.0):.2f} {c}": {
        "n_real": int(nr[:, si[(b, c)]].sum()), "n_false": int(nf[:, si[(b, c)]].sum()),
        "follow_real": float(fr[:, si[(b, c)]].sum() / max(nr[:, si[(b, c)]].sum(), 1)),
        "follow_false": float(ff[:, si[(b, c)]].sum() / max(nf[:, si[(b, c)]].sum(), 1))} for b, c in strata}
    return stat, table


def natural(split, st, rows, cl, pg_th, extra):
    """Amendment 11.1, 11.2, 13.1; package 6.2, 6.3, 15.5, 15.8; measurement 2; from the final run's natural outputs."""
    import p1v4_test_report as TR
    man = TR.final_manifest(split, st)
    dec = {n: TR.decisions(e) for n, e in man.items() if os.path.exists(e["path"])}
    out = {"missing": [n for n, e in man.items() if not os.path.exists(e["path"])]}
    if split != "dev" and out["missing"]:
        raise SystemExit(f"natural outputs missing on {split}: {out['missing']}")
    sg = S.load_groups(split)
    T = {n: S.unit_table(rows, d, sg) for n, d in dec.items()}
    rd = st["readouts"]
    cand_ro = [n for n in rd if n not in ("control starts", "extra", st["main"]["name"])]   # amendment 1.4 (review M6)
    for n, (ths, thr) in {**{m: (rd[m]["th_s"], rd[m]["th_r"]) for m in cand_ro},
                          **{m: (e["th_s"], e["th_r"]) for m, e in extra.items()}}.items():
        p = f"{R}/final/{split}/readouts/scores_{n.replace(' ', '_')}.json"
        if os.path.exists(p):
            dec[n] = S.decide(TR.keyed(json.load(open(p))), ths, thr)
            T[n] = S.unit_table(rows, dec[n], sg)
        elif split != "dev":
            raise SystemExit(f"{p} missing (amendment 1.4, package v0.6 15.5)")
    ours = TR.OURS
    # amendment 1.4 and package 15.8 (post-fix review M6): every read-out candidate's natural scores (no threshold)
    names_c = {"old head": "L1", "L2": "L2", "L3": "L3", **{m: m for m in cand_ro}, "2d": ours}
    out["candidates"] = {}
    for n, key in names_c.items():
        if key in T:
            m = S.metrics(T[key])
            out["candidates"][n] = {"five_part": m["primary"], "must_listen": m["audio"], "parts": m["parts"],
                                    "floors": m["floors"], "floor_mean": m["floor_mean"],
                                    "unseen_parts": m["unseen_parts"], "unseen": m["unseen"]}
    comps = {}
    for a, b, w in ((ours, "L1", "primary"), (ours, "L1", "audio"), ("L1", "T", "primary"),
                    ("step 2 ears", ours, "primary"), ("step 2 ears", ours, "audio")):
        if a in T and b in T:
            c = S.interval(T[a], T[b], w)
            us = sorted(set(T[a]) & set(T[b]))
            clu = {u: tuple(T[a][u][f] for f in GR.FACT) for u in us}
            comps[f"{a} - {b} ({w})"] = t_ci(c, us, clu)
    if ours in T and "L1" in T:                                        # 15.9: "keeps natural accuracy"
        k = comps[f"{ours} - L1 (primary)"]
        comps["keeps natural accuracy (lower bound > -0.03)"] = bool(k["ci95"][0] > -0.03)
        comps["five parts, ours and L1"] = {n: S.metrics(T[n])["parts"] for n in (ours, "L1")}
    # 11.1 perception gap, both modes (amendment 13.1)
    modes = TR.api_modes(split)
    out["perception_gap"] = perception_gap(split, st, rows, sg, modes, pg_th)
    # 11.2 registered natural comparisons (decision-level proportions, unit clusters, t intervals)
    main_rows = [r for r in rows if r["subset"] is None]          # package 4.1 and 6.3: main body (review M2)
    pts = GR.natural_points(main_rows, C.Context(split))
    rh = [p for p in pts if p["part"] == "r_hear"]
    hard = [p for p in rh if p["conf"] is not None and 0.5 <= p["conf"] < 0.9]
    quiet = [p for p in rh if not p["real"] and (p["conf"] is None or p["conf"] < 0.5)]

    def prop_diff(sel, a, b, ok):
        us = sorted({p["key"][0] for p in sel})
        n = np.array([sum(1 for p in sel if p["key"][0] == u) for u in us], float)
        xa = np.array([sum(ok(dec[a], p) for p in sel if p["key"][0] == u) for u in us], float)
        xb = np.array([sum(ok(dec[b], p) for p in sel if p["key"][0] == u) for u in us], float)
        se, one = GR.boot_se(us, cl, lambda w: (w * xa).sum(1) / (w * n).sum(1) - (w * xb).sum(1) / (w * n).sum(1))
        pt = float(xa.sum() / n.sum() - xb.sum() / n.sum())
        t = GR.t_interval(us, cl, se, one, pt)
        return {"a": float(xa.sum() / n.sum()), "b": float(xb.sum() / n.sum()), "n": int(n.sum()), "point": pt,
                **{k: t[k] for k in ("ci95", "ci95_normal", "df", "dominant_factor", "n_clusters")},
                "better (interval above 0)": bool(t["ci95"][0] > 0)}

    def right(d, p):
        return d.get(p["key"], {}).get("R") == p["gold"]

    def false_event(d, p):
        return d.get(p["key"], {}).get("R") != p["gold"]
    for b in ("L1", "step 2 ears", "B2-fast", "B2-strong", "B3"):
        if b in dec and ours in dec and hard:
            comps[f"hard subset (64 on dev): {ours} - {b}"] = prop_diff(hard, ours, b, right)
    if "L1" in dec and quiet:
        comps[f"no event, label < 0.5, false events: {ours} - L1"] = prop_diff(quiet, ours, "L1", false_event)
    out["comparisons"] = comps
    trust = GR.natural_report(pts, {n: d for n, d in dec.items() if n in (ours, "L1", "step 2 ears", "B2-fast",
                                                                       "B2-strong", "B3", "B1-strong", "T")})["trust"]
    for band, row in trust.items():                                    # 6.2: band intervals (per-unit clusters)
        lo, hi = (float(x) for x in band.split("-"))
        sel = [p for p in rh if p["conf"] is not None and lo <= p["conf"] < (hi if hi < 1.0 else 1.01)]
        us = sorted({p["key"][0] for p in sel})
        n = np.array([sum(1 for p in sel if p["key"][0] == u) for u in us], float)
        for name in [k for k in row if k not in ("n", "precision", "step_rule_follow")]:
            x = np.array([sum(dec[name].get(p["key"], {}).get("R") == "not" for p in sel if p["key"][0] == u)
                          for u in us], float)
            se, one = GR.boot_se(us, cl, lambda w, x=x: (w * x).sum(1) / (w * n).sum(1))
            t = GR.t_interval(us, cl, se, one, row[name])
            row[f"{name} ci95"] = [max(t["ci95"][0], 0.0), min(t["ci95"][1], 1.0)]
    out["trust"] = trust
    with_table = {n for n in ("B2-fast", "B2-strong", "B3") if n in man and "_prec" in str(man[n].get("setting"))}
    out["reliance"] = reliance(split, rows, dec, cl, ours, with_table)
    out["reliance_stop"] = reliance_stop(rows, split, dec, cl)
    out["reliance_under_noise"] = noise_reliance(split, st, cl, with_table)
    out["errors_by_front_end_part"] = front_end_breakdown(rows, split, dec, (ours, "L1", "T", "B2-fast", "B2-strong",
                                                                            "B3", "B2-ideal"))
    out["noise_floor"] = noise_floor(split, st, man)
    out["api_repeat_flips"] = api_repeat_flips(split, st)
    items = GR.word_items(main_rows)
    wc = {n: GR.words_channel(items, dec[n]) for n in (ours, "L1") if n in dec}
    if len(wc) == 2:
        pa, pb = wc[ours]["_per_unit"], wc["L1"]["_per_unit"]
        Tm = S.unit_table(rows, {}, sg)
        us = sorted(u for u in pa if pa[u][0] > 0 and u in Tm)
        n = np.array([pa[u][0] for u in us], float)
        ea = np.array([pa[u][1] for u in us], float)
        eb = np.array([pb.get(u, [0, 0, 0])[1] for u in us], float)
        clw = {u: tuple(Tm[u][f] for f in GR.FACT) for u in us}
        se, one = GR.boot_se(us, clw, lambda w: (w * ea).sum(1) / (w * n).sum(1) - (w * eb).sum(1) / (w * n).sum(1))
        pt = float(ea.sum() / n.sum() - eb.sum() / n.sum())
        out["words_channel"] = {n_: {k: v for k, v in x.items() if not k.startswith("_")} for n_, x in wc.items()}
        out["words_channel"][f"{ours} - L1: event-led error rate"] = {"point": pt,
                                                                        **GR.t_interval(us, clw, se, one, pt)}
    return out


def perception_gap(split, st, rows, sg, modes, pg_th):
    """Amendment 11.1 and 13.1: B2-ideal minus B2-strong. Probabilities: the same setting (K48, no thinking, with the
    table). Answers: the same setting, and B2-strong's main answers setting; the sentence uses the smaller."""
    import p1v4_api as A
    import p1v4_test_report as TR
    out = {}
    F = f"{R}/final/{split}/api"
    ideal_mode = modes.get("B2-ideal", "probabilities")
    e_i = A.effective("b2ideal", split, ideal_mode, st)          # post-fix review minor 6: a re-choice is used
    if e_i.get("th_s") is None:
        if split != "dev":
            raise SystemExit(f"B2-ideal has no {ideal_mode} thresholds in the record (amendment 11.1)")
        return {"not computed": f"B2-ideal has no {ideal_mode} thresholds in the record"}
    sfx = "_answers" if ideal_mode == "answers" else ""
    p_i = (f"{R}/api/b2ideal/scores_dev_{e_i['setting']}.json" if split == "dev" and ideal_mode == "probabilities"
           else json.load(open(f"{RES}/answer_only_dev.json"))["B2-ideal"]["chosen"]["path"] if split == "dev"
           else f"{F}/b2ideal/scores_{split}_{e_i['setting']}{sfx}.json")
    if not os.path.exists(p_i):
        if split != "dev":
            raise SystemExit(f"{p_i} missing (perception gap, amendment 11.1)")
        return {"not computed": f"{p_i} missing"}
    Ti = S.unit_table(rows, S.decide(TR.keyed(json.load(open(p_i))), e_i["th_s"], e_i["th_r"]), sg)
    mode = modes.get("B2-strong", "probabilities")
    e = A.effective("b2strong", split, mode, st)
    cands = []
    if mode == "probabilities":
        fz = st["api"]["B2-strong"]["probabilities"]
        cands.append(("same setting (K48 no thinking), probabilities", "K48_nothink_prec", fz["th_s"], fz["th_r"], False))
        if e["setting"] != "K48_nothink_prec":
            cands.append((f"B2-strong re-chosen setting ({e['setting']})", e["setting"], e["th_s"], e["th_r"], False))
    else:
        cands.append(("same setting (K48 no thinking), answers", "K48_nothink_prec", pg_th["th_s"], pg_th["th_r"], True))
        cands.append((f"B2-strong main answers setting ({e['setting']})", e["setting"], e["th_s"], e["th_r"], True))
    for label, setting, ts, tr_, answers in cands:
        if split == "dev":
            log = {x["setting"]: x for x in json.load(open(f"{RES}/answer_only_dev.json"))["B2-strong"]["log"]}
            p_s = (f"{R}/api/b2strong/answers/scores_dev_{setting}.json" if answers
                   else f"{R}/api/b2strong/scores_dev_{setting}.json")
            if answers and not os.path.exists(p_s) and setting in log:
                p_s = log[setting].get("path", p_s)
        else:
            p_s = f"{F}/b2strong/scores_{split}_{setting}{'_answers' if answers else ''}.json"
        if not os.path.exists(p_s):
            if split != "dev":
                raise SystemExit(f"{p_s} missing (perception gap, amendment 13.1)")
            out[label] = {"not computed": p_s}
            continue
        Ts = S.unit_table(rows, S.decide(TR.keyed(json.load(open(p_s))), ts, tr_), sg)
        c = S.interval(Ti, Ts, "primary")
        us = sorted(set(Ti) & set(Ts))
        out[label] = t_ci(c, us, {u: tuple(Ti[u][f] for f in GR.FACT) for u in us})
    vals = [v["point"] for v in out.values() if "point" in v]
    if vals:
        out["sentence uses (the smaller)"] = min(vals)
    return out


def reliance(split, rows, dec, cl, ours, with_table=("B2-fast", "B2-strong", "B3")):
    """Package 15.5: G7a, G7b and the reported reliance tables on natural R-hear points; conflicts between label and
    ears probe (7.3); the readers against their table's step rule (only readers whose prompt held the table: review
    minor 5); the best label-only rule (15.8)."""
    pts = label_points(rows, split)
    units = sorted({p["unit"] for p in pts})
    follow = {n: {p["key"]: d.get(p["key"], {}).get("R") == "not" for p in pts} for n, d in dec.items()}
    out = {"n_points": len(pts), "n_real": sum(p["real"] for p in pts), "systems": {}}
    stats = {}
    for n in dec:
        if not any(p["key"] in dec[n] for p in pts):
            continue
        stat, table = cmh(pts, follow[n], units, cl)
        pt = float(stat(np.ones((1, len(units))))[0])
        se, one = GR.boot_se(units, cl, stat)
        out["systems"][n] = {"gap": pt, **{k: v for k, v in GR.t_interval(units, cl, se, one, pt).items()
                                           if k in ("ci95", "ci95_normal", "df", "dominant_factor", "n_clusters")},
                             "strata": table}
        stats[n] = stat
    if ours in stats:
        g7a = dict(out["systems"][ours])
        g7a = {k: g7a[k] for k in ("gap", "ci95", "ci95_normal", "df", "dominant_factor", "n_clusters")}
        g7a["pass"] = bool(g7a["ci95"][0] > 0)
        out["G7a: main's follow gap (real - false label), lower bound > 0"] = g7a
        if "T" in stats:
            sa, sb = stats[ours], stats["T"]
            pt = float(sa(np.ones((1, len(units))))[0] - sb(np.ones((1, len(units))))[0])
            se, one = GR.boot_se(units, cl, lambda w: sa(w) - sb(w))
            t = GR.t_interval(units, cl, se, one, pt)
            out["G7b: main's gap - T's gap, lower bound > 0"] = {
                "point": pt, **{k: t[k] for k in ("ci95", "ci95_normal", "df", "dominant_factor", "n_clusters")},
                "pass": bool(t["ci95"][0] > 0)}
        mc = {}                                    # post-fix review minor 1: seeds 1-6 (the verdict uses seed 1)
        for seed in (1, 2, 3, 4, 5, 6):
            se_a, one_a = GR.boot_se(units, cl, stats[ours], seed=seed)
            mc.setdefault("G7a", {})[seed] = GR.t_interval(units, cl, se_a, one_a, g7a["gap"])["ci95"][0]
            if "T" in stats:
                se_b, one_b = GR.boot_se(units, cl, lambda w: sa(w) - sb(w), seed=seed)
                mc.setdefault("G7b", {})[seed] = GR.t_interval(units, cl, se_b, one_b, pt)["ci95"][0]
        out["monte_carlo_seeds"] = {k: {"lower_bound_by_seed": v, "passes_out_of_6": sum(x > 0 for x in v.values()),
                                        "same_verdict_in_all_seeds": len({x > 0 for x in v.values()}) == 1}
                                    for k, v in mc.items()}
        if "step 2 ears" in stats:
            out["step 2 ears gap above main's (trade-off sentence)"] = bool(
                out["systems"]["step 2 ears"]["gap"] > out["systems"][ours]["gap"])
    # 7.3 conflicts: label says (>= 0.9) and the ears probe hears (>= 0.5) disagree
    zp = f"{R}/final/{split}/readouts/feats_natural.npz"
    if os.path.exists(zp):
        z = np.load(zp)
        pe = CV.probe_p(z["ears"], dict(np.load(f"{R}/readout/ears_probe.npz")))
        pos = {}
        for w, idv in enumerate(z["ids"]):
            u, v, k = idv.split("|")
            pos[(u, v, int(k))] = float(pe[w])
        conf = [p for p in pts if p["key"] in pos and (p["conf"] >= CV.LABEL_TRUST) != (pos[p["key"]] >= CV.EARS_CUT)]
        out["conflicts"] = {"n": len(conf), "label right": sum(p["real"] for p in conf),
                            "share following the correct side": {
                                n: float(np.mean([follow[n][p["key"]] == p["real"] for p in conf])) for n in stats}
                            if conf else {}}
    # readers against the step rule of the table they were given
    tab = reliability_table()
    rr = {}
    for n in ("B2-fast", "B2-strong", "B3"):
        if n not in stats:
            continue
        if n not in with_table:
            rr[n] = {"not computed": "this setting's prompt had no reliability table"}
            continue
        ui = {u: i for i, u in enumerate(units)}
        ex, cnt = np.zeros(len(units)), np.zeros(len(units))
        for p in pts:
            rule = tab.get((p["cls"], p["band"]), 0.0) > 0.5
            ex[ui[p["unit"]]] += float(follow[n][p["key"]]) - float(rule)
            cnt[ui[p["unit"]]] += 1
        pt = float(ex.sum() / cnt.sum())
        se, one = GR.boot_se(units, cl, lambda w, ex=ex, cnt=cnt: (w @ ex) / np.maximum(w @ cnt, 1e-9))
        t = GR.t_interval(units, cl, se, one, pt)
        rr[n] = {"excess_follow": pt, **{k: t[k] for k in ("ci95", "ci95_normal", "df", "n_clusters")},
                 "over-follow (interval above 0)": bool(t["ci95"][0] > 0)}
    out["readers_vs_table_rule"] = rr
    # best label-only rule on these points (an oracle per class threshold on the label's confidence)
    best = {}
    for cls in sorted({p["cls"] for p in pts}):
        ps = [p for p in pts if p["cls"] == cls]
        cand = sorted({p["conf"] for p in ps}) + [1.01]
        acc = {c: np.mean([(p["conf"] >= c) == (p["gold"] == "not") for p in ps]) for c in cand}
        c_best = max(acc, key=acc.get)
        best[cls] = {"threshold": float(c_best), "accuracy": float(acc[c_best]), "n": len(ps)}
    n_all = sum(b["n"] for b in best.values())
    oracle = sum(b["accuracy"] * b["n"] for b in best.values()) / max(n_all, 1)
    out["best_label_only_rule"] = {"by_class": best, "accuracy": oracle,
                                   "reliance error (oracle - system accuracy on these points)": {
                                       n: float(oracle - np.mean([dec[n].get(p["key"], {}).get("R") == p["gold"]
                                                                  for p in pts])) for n in stats}}
    return out


def words(text):
    return re.findall(r"[a-z0-9']+", str(text).lower())


def front_end_breakdown(rows, split, dec, names):
    """Package 15.8 (reported; review M5): R-hear main-body errors split by which front-end part was wrong:
    the Whisper turbo transcript of the line (the readers' transcript; wrong = any word differs), the line's speaker
    tag, and the event label in the window (right event label >= 0.5, false label >= 0.5, missed event, clean)."""
    ctx = C.Context(split, asr="turbo")
    ex = S.excluded_units()
    cells = collections.defaultdict(lambda: collections.defaultdict(list))
    for r in rows:
        if r["unit"] in ex or r["part"] != "r_hear" or r["subset"] is not None:
            continue
        p = r["points"][0]
        tr, _, tags, snd = ctx.point(r, p["k"])
        src = {s["id"]: s for s in r["sources"]}
        line = p.get("line")
        if not line or line not in src:
            continue
        asr_ok = words(tr.get(line, "")) == words(src[line].get("text", ""))
        tag_ok = (tags.get(line) == "user") == (src[line].get("who") == "user")
        conf = max([s[3] for s in snd if RO.in_window(s, p["t"])], default=0.0)
        real = RO.is_real(r, p["t"])
        lab = ("right label" if conf >= 0.5 else "missed event") if real else ("false label" if conf >= 0.5 else "clean")
        cell = f"transcript {'ok' if asr_ok else 'wrong'} | tag {'ok' if tag_ok else 'wrong'} | {lab}"
        for n in names:
            if n in dec:
                cells[cell][n].append(dec[n].get((r["unit"], r["version"], p["k"]), {}).get("R") != p["gold"]["R"])
    return {c: {"n": len(next(iter(v.values()))), **{n: float(np.mean(x)) for n, x in v.items()}}
            for c, v in sorted(cells.items())}


def reliance_stop(rows, split, dec, cl):
    """Package 15.5, the stop version (reported; post-fix review M6): S-move main-body points of the must-listen half
    (the stop criteria's half: the visitor does not speak before the point) with a door-class detection (>= 0.2) in
    the window; "follow" = stop, label "right" = the person really walked away (gold S = stop); Cochran-Mantel-Haenszel
    over the confidence bands; every system, with the package's t interval."""
    ctx = C.Context(split)
    ex = S.excluded_units()
    pts = []
    for r in rows:
        if (r["unit"] in ex or r["part"] != "s_move" or r["subset"] is not None
                or r["spec"].get("visitor_speaks")):
            continue
        p = r["points"][0]
        if p["gold"].get("S") is None:
            continue
        _, _, _, snd = ctx.point(r, p["k"])
        door = [s for s in snd if s[0] == "door" and s[2] > p["t"] - D.WIN_S and s[1] < p["t"]]
        if not door or max(s[3] for s in door) < 0.2:
            continue
        c = float(max(s[3] for s in door))
        pts.append({"key": (r["unit"], r["version"], p["k"]), "unit": r["unit"], "cls": "door", "conf": c,
                    "band": band_of(c), "real": p["gold"]["S"] == "stop"})
    out = {"n_points": len(pts), "n_real": sum(p["real"] for p in pts), "systems": {}}
    if not pts or all(p["real"] for p in pts) or not any(p["real"] for p in pts):
        out["note"] = "no stratum with both a right and a false door label"
        return out
    units = sorted({p["unit"] for p in pts})
    for n, d in dec.items():
        if not any(p["key"] in d for p in pts):
            continue
        follow = {p["key"]: d.get(p["key"], {}).get("S") == "stop" for p in pts}
        stat, table = cmh(pts, follow, units, cl)
        pt = float(stat(np.ones((1, len(units))))[0])
        se, one = GR.boot_se(units, cl, stat)
        t = GR.t_interval(units, cl, se, one, pt)
        out["systems"][n] = {"gap": pt, **{k: t[k] for k in ("ci95", "df", "dominant_factor", "n_clusters")},
                             "strata": table}
    return out


def noise_floor(split, st, man):
    """Package 4.6 (post-fix review M6): the package's own single-pass natural run against the main run, max score
    difference and decisions flipped at the frozen thresholds: old head and main read-out (L1 family, from
    grounding/<split>/l1_natural.npz), T, L2, L3 (local_natural.json) and B1-strong (decisions)."""
    import p1v4_test_report as TR
    out = {}
    zp = f"{G.out_dir(split)}/l1_natural.npz"
    th = {"old head": (st["local"]["L1"]["th_s"], st["local"]["L1"]["th_r"]),
          "2d": (st["main"]["th_s"], st["main"]["th_r"])}
    for n in ("T", "L2", "L3"):
        th[n] = (st["local"][n]["th_s"], st["local"][n]["th_r"])

    def compare(name, new, old):
        keys = [k for k in new if k in old]
        diffs = [abs(new[k][q] - old[k][q]) for k in keys for q in new[k]
                 if new[k][q] is not None and old[k].get(q) is not None]
        a, b = S.decide({k: new[k] for k in keys}, *th[name]), S.decide({k: old[k] for k in keys}, *th[name])
        out[name] = {"n": len(keys), "max_abs_diff": float(max(diffs)) if diffs else None,
                     "median_abs_diff": float(np.median(diffs)) if diffs else None,
                     "decision_flips": sum(1 for k in keys for q in a[k] if a[k][q] != b[k].get(q))}
    if os.path.exists(zp):
        z = dict(np.load(zp))
        compare("old head", RO.scores_of(z, None, None), TR.keyed(json.load(open(man["L1"]["path"]))))
        sec = R2D.Sec(None, z["ids"], z["sec_mean"], z["sec_max"])
        compare("2d", R2D.scores_2d(z, sec, R2D.load_2d()), TR.keyed(json.load(open(man[TR.OURS]["path"]))))
    elif split != "dev":
        raise SystemExit(f"{zp} missing (package 4.6)")
    loc = GR.local_scores(split, "natural")
    if loc is not None:
        for n in ("T", "L2", "L3"):
            compare(n, loc[n], TR.keyed(json.load(open(man[n]["path"]))))
        b1 = TR.decisions(man["B1-strong"])
        out["B1-strong"] = {"n": len(loc["B1-strong"]), "decision_differences": sum(
            1 for k, d in loc["B1-strong"].items() if b1.get(k) != d)}
    elif split != "dev":
        raise SystemExit(f"package local natural run missing on {split} (package 4.6)")
    return out


def api_repeat_flips(split, st):
    """Package 4.6 (post-fix review M6): the package API's repeat sample (`--repeat`, repeat.jsonl in each condition
    folder) against the first answers of the same questions, flips at the thresholds of the setting in use."""
    out = {}
    for name, sd in API.items():
        m, e = G.api_effective(sd, split)
        d0 = G.api_dir(split, sd, e["setting"], m == "answers")
        th = {"S": e["th_s"], "R": e["th_r"]}
        n = flips = 0
        by = {}
        for cond in G.MATCHED + G.MOVE_CONDS:
            rp, p = os.path.join(d0, cond, "repeat.jsonl"), os.path.join(d0, cond, "responses.jsonl")
            if not (os.path.exists(rp) and os.path.exists(p)):
                continue
            first = {}
            for line in open(p, encoding="utf-8"):
                rec = json.loads(line)
                if rec["status"] == 200:
                    first.setdefault((rec["id"], rec["q"]), rec["score"])
            nc = fc = 0
            for line in open(rp, encoding="utf-8"):
                rec = json.loads(line)
                k = (rec["id"], rec["q"])
                if rec["status"] != 200 or k not in first:
                    continue
                nc += 1
                fc += (rec["score"] >= th[rec["q"]]) != (first[k] >= th[rec["q"]])
            if nc:
                by[cond] = {"n": nc, "flips": fc}
                n, flips = n + nc, flips + fc
        out[name] = {"setting": e["setting"], "mode": m, "n": n, "flips": flips,
                     "flip_rate": flips / n if n else None, "by_condition": by}
        if split != "dev" and n == 0:
            raise SystemExit(f"{name}: no repeat sample on {split} (package 4.6: run the package API with --repeat)")
    return out


def noise_reliance(split, st, cl, with_table=("B2-fast", "B2-strong", "B3")):
    """Package 15.5 (reported): the reliance table at each level of the noise analysis (p1v4_noise_final outputs:
    data/p1v4/runs/final/<split>/noise/<level>/), with the main system as "2d"; the gap of the main system minus T."""
    import p1v4_api as API
    import p1v4_noise_final as NF
    import p1v4_test_report as TR
    NF.patch_folders()
    modes = TR.api_modes(split)
    th = {"2d": (st["main"]["th_s"], st["main"]["th_r"])}
    for n in ("L1", "L2", "L3", "T"):
        th[n] = (st["local"][n]["th_s"], st["local"][n]["th_r"])
    files = {"2d": "2d", "L1": "L1", "L2": "L2", "L3": "L3", "T": "T", "B1-strong": "B1-strong"}
    for sd, n in NF.API_NAME.items():
        e = API.effective(sd, split, modes[n], st)
        th[n] = (e["th_s"], e["th_r"])
        files[n] = f"{n}_{modes[n]}"
    out = {}
    for v in NF.VARIANTS:
        d = os.path.join(R, "final", split, "noise", v)
        if not os.path.isdir(d):
            continue
        dec = {}
        for n, f in files.items():
            p = os.path.join(d, f"{f}.json")
            if os.path.exists(p):
                x = NF.keyed(json.load(open(p)))
                dec[n] = x if n == "B1-strong" else S.decide(x, *th[n])
        rows_v = D.load_rows(f"{split}_{v}")
        r = reliance(f"{split}_{v}", rows_v, dec, cl, "2d", with_table)
        out[v] = {k: x for k, x in r.items() if k != "conflicts"}
    return out


# ------------------------------------------------------------------------------------------------ self-test

def selftest():
    """Amendment 4.5 on a changed dev copy (in memory): units relabelled as subsets must leave the criteria; groups
    whose versions get different text in one condition must be dropped; above 2% dropped the measurement is invalid."""
    import copy as _copy
    import random as _random
    rows, _ = G.load("dev")
    groups = G.load_groups("dev")
    rng = _random.Random(5)
    rh = sorted(g["unit"] for g in groups if g["part"] == "r_hear")
    sm = sorted(g["unit"] for g in groups if g["part"] == "s_move")
    relabel = set(rng.sample(rh, 10) + rng.sample(sm, 4))
    rest = [u for u in rh + sm if u not in relabel]

    def row_hook(rows_):
        out_ = []
        for r in rows_:
            if r["unit"] in relabel:
                r = _copy.deepcopy(r)
                r["subset"] = "piper" if r["part"] == "r_hear" else "new_rec"
            out_.append(r)
        return out_

    def run(n_bad, tag):
        bad = set(rng.sample(rest, n_bad))

        def z_hook(cond, z):
            if cond != "c0.5":
                return z
            z = dict(z)
            sha = np.array(z["text_sha"], dtype=object)
            for i, idv in enumerate(z["ids"]):
                u, v, _ = idv.split("|")
                if u in bad and v == "1":
                    sha[i] = "corrupted"
            z["text_sha"] = sha
            return z
        res = main("dev", out=f"{RES}/grounding_v06_selftest_{tag}.json", row_hook=row_hook, z_hook=z_hook,
                   with_natural=False)
        ident = res["identity"]
        main_n = sum(ident["n_main_groups"].values())
        return {"relabelled_out_of_criteria": main_n == len(rh) + len(sm) - len(relabel) - n_bad,
                "dropped_equals_corrupted": set(ident["dropped_groups"]) == bad,
                "dropped_share": ident["dropped_share_main"], "invalid": ident["invalid"],
                "criteria_reported": "invalid" not in res["criteria"]}
    a = run(3, "few")
    b = run(8, "many")
    ok = (a["relabelled_out_of_criteria"] and a["dropped_equals_corrupted"] and not a["invalid"]
          and a["criteria_reported"] and b["dropped_equals_corrupted"] and b["invalid"] and not b["criteria_reported"])
    rep = {"relabelled": len(relabel), "few (3 corrupted groups)": a, "many (8 corrupted groups)": b, "pass": ok}
    json.dump(rep, open(f"{RES}/grounding_v06_selftest.json", "w"), indent=1)
    print("SELFTEST", "PASS" if ok else "FAIL", json.dumps(rep))


def show(res):
    print("missing:", res["missing"])
    print("dev fallbacks:", res.get("dev_fallbacks"))
    print("identity:", json.dumps({k: v for k, v in res["identity"].items() if k != "dropped_groups"}))
    print("api modes:", res.get("api_modes"))
    K = res["criteria"]
    if isinstance(K, dict) and "invalid" in K:
        print("CRITERIA INVALID:", K["invalid"])
        return

    def line(tag, k, c):
        p = c.get("point", c.get("gap"))
        flag = " ".join(f"{f}={c[f]}" for f in ("pass", "rise_below_0.20", "drop_below_0.20") if f in c)
        print(f"[{tag}] {k}: {p:+.3f} [{c['ci95'][0]:+.3f}, {c['ci95'][1]:+.3f}] (t df {c.get('df')}, "
              f"{c.get('dominant_factor')}) {flag}")
    for k, c in K.get("grounded", {}).items():
        line("grounded", k, c)
    for k, c in K.items():
        if k.startswith("G1b") or k.startswith("G4b:"):
            line(k[:3], k, c)
    for k, c in K.get("score", {}).items():
        line("score", k, c)
    for k in [x for x in K if x.startswith("G4b (offsets file") or x == "G5 (own run)"]:
        print(k, json.dumps(K[k]))
    for k, v in res["reported"].get("monte_carlo_seeds", {}).items():
        print(f"[seeds 1-6] {k}: passes {v['passes_out_of_6']}/6, lower bounds "
              f"{[round(x, 3) for x in v['lower_bound_by_seed'].values()]}")
    print("old head wording:", json.dumps({p: {k: x[k] for k in ("decision_concordance", "did_not_change_with_the_audio",
                                                                  "direction")}
                                           for p, x in res["reported"].get("old_head_wording", {}).items()}))
    print("subsets:", json.dumps({s: {p: x["n_groups"] for p, x in d.items()}
                                  for s, d in res["reported"].get("subsets", {}).items()}))
    for part, d in res["reported"].get("heard_then_overridden", {}).items():
        for n, c in d.items():
            line(f"heard then overridden {part}", n, c)
    nat = res.get("natural", {})
    for k, v in nat.get("comparisons", {}).items():
        if isinstance(v, dict) and "ci95" in v:
            line("natural", k, v)
    rel = nat.get("reliance", {})
    for k in ("G7a: main's follow gap (real - false label), lower bound > 0", "G7b: main's gap - T's gap, lower bound > 0"):
        if k in rel:
            line("G7", k, rel[k])
    for k, v in rel.get("monte_carlo_seeds", {}).items():
        print(f"[seeds 1-6] {k}: passes {v['passes_out_of_6']}/6, lower bounds "
              f"{[round(x, 3) for x in v['lower_bound_by_seed'].values()]}")
    print("perception gap:", json.dumps(nat.get("perception_gap")))
    print("noise floor:", json.dumps(nat.get("noise_floor")))
    print("api repeat flips:", json.dumps({n: [x["n"], x["flips"]] for n, x in nat.get("api_repeat_flips", {}).items()}))
    rs = nat.get("reliance_stop", {})
    print("stop reliance:", rs.get("n_points"), "points,", rs.get("n_real"), "right;",
          json.dumps({n: round(x["gap"], 3) for n, x in rs.get("systems", {}).items()
                      if n in ("ours", "L1", "T", "L2", "B3", "B2-fast", "B2-strong")}))
    print("candidates (five-part, must-listen):", json.dumps({n: [round(c["five_part"], 3), round(c["must_listen"], 3)]
                                                             for n, c in nat.get("candidates", {}).items()}))


if __name__ == "__main__":
    if sys.argv[1] == "selftest":
        selftest()
    else:
        main(sys.argv[1])
